@DataJpaTest
class OrderRepositoryTest {
    @Autowired
    private OrderRepository orderRepository;

    @Autowired
    private TestEntityManager entityManager;

    @Test
    void shouldFindOrdersByCustomerEmail() {
        var customer = new Customer(null, "alice@example.com");
        entityManager.persist(customer);

        var order1 = new Order(null, "Laptop", 1500.00, customer);
        var order2 = new Order(null, "Mouse", 25.00, customer);
        entityManager.persistAndFlush(order1);
        entityManager.persistAndFlush(order2);

        var orders = orderRepository.findByCustomerEmail("alice@example.com");

        assertEquals(2, orders.size());
        assertTrue(orders.stream().anyMatch(o -> o.getItem().equals("Laptop")));
    }
}
