@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock
    private OrderRepository orderRepository;
    @Mock
    private InventoryService inventoryService;
    private OrderService orderService;

    @BeforeEach
    void setUp() {
        orderService = new OrderService(orderRepository, inventoryService);
    }

    @Test
    void placeOrder_savesOrderAndReducesInventory() {
        var order = new Order(1L, "Laptop", 2);
        when(inventoryService.reserveStock("Laptop", 2)).thenReturn(true);
        when(orderRepository.save(order)).thenReturn(order);

        var result = orderService.placeOrder(order); // @Transactional ignored here

        verify(inventoryService).reserveStock("Laptop", 2);
        verify(orderRepository).save(order); // verify business logic flow
        assertEquals(order, result);
    }
}
