@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock
    private OrderRepository orderRepository;
    private OrderService orderService;

    @BeforeEach
    void setUp() {
        orderService = new OrderService(orderRepository);
    }

    @Test
    void findOrder_throwsOrderNotFoundWhenRepositoryFails() {
        Long orderId = 999L;
        // Stub repository to throw exception
        when(orderRepository.findById(orderId))
            .thenThrow(new DataAccessException("Database connection failed") {});

        var exception = assertThrows(OrderNotFoundException.class,
            () -> orderService.findOrder(orderId));

        assertEquals("Order 999 not found", exception.getMessage());
        assertInstanceOf(DataAccessException.class, exception.getCause()); // verify wrapped cause
    }
}
